import {accountControls} from './accounts.js';
import {subjects,ages} from './curriculum.js';
export function navigation({age,page,xp,user,status}){const young=age==='primary';const experience=ages.find(a=>a.id===age)||ages[2];return `<header class="app-header nav-${age}"><button class="brand-home" data-page="home" aria-label="NEXORA home"><span class="brand"><span class="mark" aria-hidden="true">N</span>NEXORA</span><span class="brand-tagline">Learn. Explore. Innovate.</span></button><span class="experience-label">${experience.name}</span><nav class="header-navigation" aria-label="Main navigation"><button data-page="home" class="${page==='home'?'selected':''}">${young?'⌂ My world':'Dashboard'}</button><details class="subject-menu"><summary>${young?'◈ Adventures':age==='middle'?'Explore subjects':'Subjects'} <span aria-hidden="true">⌄</span></summary><div class="subject-dropdown">${subjects.map(s=>`<button data-subject="${s.id}"><span aria-hidden="true">${s.icon}</span>${s.name}</button>`).join('')}</div></details><button data-page="progress" class="${page==='progress'?'selected':''}">${young?'☆ My stars':'Learning Progress'}</button><button data-page="settings" class="${page==='settings'?'selected':''}">${young?'☷ Settings':'Learning Preferences'}</button><button class="header-tutor" data-tutor-open>✦ ${young?'Ask a helper':'AI Learning Assistant'}</button></nav><div class="header-account">${accountControls(user,status)}</div></header>`}
